def find_path(graph, start, goal):
    forward_queue = deque([(start, [])])
    backward_queue = deque([(goal, [])])
    forward_visited = set()
    backward_visited = set()

    def bfs(queue, visited):
        while queue:
            current, path = queue.popleft()
            if current in visited:
                continue
            visited.add(current)
            if current == start:
                return path + [current]
            for neighbor in graph.get(current, []):
                queue.append((neighbor, path + [current]))
        return None
    forward_path = bfs(forward_queue, forward_visited)
    if not forward_path:
        return None
    backward_path = bfs(backward_queue, backward_visited)
    if not backward_path:
        return None
    backward_path.reverse()
    intersection = set(forward_path).intersection(set(backward_path))
    if not intersection:
        return None
    return forward_path + backward_path
