    bidirectional_open_set[0].append((0, start))
    bidirectional_open_set[1].append((0, goal))
    came_from_start = {}
    came_from_goal = {}
    cost_so_far_start = {}
    cost_so_far_goal = {}
    came_from_start[start] = None
    came_from_goal[goal] = None
    cost_so_far_start[start] = 0
    cost_so_far_goal[goal] = 0
    while bidirectional_open_set[0] or bidirectional_open_set[1]:
        if not bidirectional_open_set[0]:
            bidirectional_open_set[0], bidirectional_open_set[1] = (bidirectional_open_set[1], bidirectional_open_set[0])
            came_from_start, came_from_goal = (came_from_goal, came_from_start)
            cost_so_far_start, cost_so_far_goal = (cost_so_far_goal, cost_so_far_start)
            visited_start, visited_goal = (visited_goal, visited_start)
            start, goal = (goal, start)
        current_cost, current_node = heapq.heappop(bidirectional_open_set[0])
        if current_node in visited_start:
            continue
        visited_start.add(current_node)
        if current_node == goal:
            break
        for next_node in graph.get(current_node, []):
            if next_node in visited_start:
