def find_path(graph, start, goal):
    frontier_start = {start}
    frontier_end = {goal}
    explored_start = set()
    explored_end = set()
    parents = {start: None}
    parents[goal] = None
    while frontier_start and frontier_end:
        if len(frontier_start) > len(frontier_end):
            frontier_start, frontier_end = (frontier_end, frontier_start)
            start, goal = (goal, start)
            parents = {goal: None}
            explored_start, explored_end = (explored_end, explored_start)
        current = frontier_start.pop()
        if current in explored_start:
            continue
        explored_start.add(current)
        if current == goal:
            path = [current]
            while current is not None:
                current = parents[current]
                if current is not None:
                    path.append(current)
            path.reverse()
            return path
        for neighbor in graph.get(current, []):
            if neighbor in explored_start:
                continue
            if neighbor in frontier_start:
                continue
            frontier_start.add(neighbor)
            parents[neighbor] = current
        for neighbor in graph.get(current, []):
            if neighbor in explored_end:
                continue
            if neighbor in frontier_end:
                continue
            frontier_end.add(neighbor)
            parents[neighbor] = current
