def find_path(graph, start, goal):
    open_set_start = [(0, start)]
    open_set_goal = [(0, goal)]
    came_from_start = {}
    came_from_goal = {}
    g_score_start = {start: 0}
    g_score_goal = {goal: 0}
    f_score_start = {start: heuristic(start, goal)}
    f_score_goal = {goal: heuristic(start, goal)}
    while open_set_start and open_set_goal:
        current_start = min(open_set_start, key=lambda p: p[0])[1]
        current_goal = min(open_set_goal, key=lambda p: p[0])[1]
        if current_start == current_goal:
            path = []
            while current_start in came_from_start:
                path.append(current_start)
                current_start = came_from_start[current_start]
            path.append(current_start)
            return path[::-1]
        open_set_start.remove((f_score_start[current_start], current_start))
        open_set_goal.remove((f_score_goal[current_goal], current_goal))
        for neighbor in graph[current_start]:
            tentative_g_score_start = g_score_start[current_start] + 1
            if neighbor not in g_score_start or tentative_g_score_start < g_score_start[neighbor]:
                came_from_start[neighbor] = current_start
                g_score_start[neighbor] = tentative_g_score_start
                f_score_start[neighbor] = tentative_g_score_start + heuristic(neighbor, goal)
                if neighbor not in open_set_start:
                    heapq.heappush(open_set_start, (f_score_start[neighbor], neighbor))
        for neighbor in graph[current_goal]:
            tentative_g_score_goal = g_score_goal[current_goal] + 1
            if neighbor not in g_score_goal or tentative_g_score_goal < g_score_goal[neighbor]:
